mapper.update:
UPDATE pay09_relate_note
   SET pay09_pay_date  = #{req.payDate},
       pay09_pay_cd    = #{req.payCd},
       pay09_note_type = #{req.noteType},
       pay09_person_id = #{req.personId},
       pay09_note      = #{req.note}
 WHERE pay09_relate_note_id = #{req.relateNoteId}
   AND pay09_company_id     = #{companyId}

